--ptf-bnd-noteimg-n1
Content-Type: text/javascript; charset=utf-8
Content-Disposition: attachment; filename="fluid.demos.ai.noteSeededImageGenerator"
Content-Description: layer

fluid.def("fluid.demos.ai.noteSeededImageGenerator", {
    $layers: ["fluid.demos.imageGenerator", "fluid.topLevelWidget"],
    noteFinder: {
        $component: {
            $layers: "fluid.demos.closestNoteFinder",
            view: "{noteSeededImageGenerator}.view"
        }
    },
    state: {
        prompt: "{noteFinder}.noteText"
    },
    cannotGenerate: "$compute:fluid.demos.ai.noteSeededImageGenerator.canGenerate({noteFinder}.distance, {self}.state.prompt, {self}.state.isGenerating)"
});

// As for the original, but disabled while no sticky note is in view, since the prompt then holds a status message
fluid.demos.ai.noteSeededImageGenerator.canGenerate = (distance, prompt, isGenerating) =>
    distance !== null && !isGenerating && prompt.trim() !== "";
--ptf-bnd-noteimg-n1
